    transfer: [
      B.text('c1_020_t_situation', 'Kontroll: kirjutamine ja rääkimine (Harno C1)', 'Selle lehe osad on nagu Harno C1 eksamil. Kirjutamine 2: arvamuslugu 220–260 sõna (umbes 45 minutit). Rääkimine paaris: 2-minutiline kõne pärast 3-minutilist ettevalmistust, partneri küsimused ja umbes 7-minutiline arutelu. Kirjutamise osa 1 (andmete kokkuvõtte) tegid Avasta lehel. Olukord: vanalinna hoovide programm on aasta kestnud ja linn otsustab, kas seda laiendada. Kohalik ajaleht kogub arvamusi.'),
      B.errorfix('c1_020_t_fix', 'Enne kirjutamist: tüüpvead.', 'Igas lauses on üks sõnajärje või käände viga. Paranda.', [['Pärast pikka avalikku arutelu linn muutis kava, et see arvestaks rohkem elanike huvidega.', 'Pärast pikka avalikku arutelu muutis linn kava, et see arvestaks rohkem elanike huvidega.'], ['Ühistu esimees töötas varem arhitektiks ühes suures Tallinna projekteerimisbüroos.', 'Ühistu esimees töötas varem arhitektina ühes suures Tallinna projekteerimisbüroos.'], ['Hoov muutus elanike jaoks viimasena privaatseks ruumiks, kus lapsed saavad turvaliselt mängida.', 'Hoov muutus elanike jaoks viimaseks privaatseks ruumiks, kus lapsed saavad turvaliselt mängida.'], ['Seetõttu ühistu otsustas programmiga liituda, kuid ainult kindlatel tingimustel.', 'Seetõttu otsustas ühistu programmiga liituda, kuid ainult kindlatel tingimustel.'], ['Esimesel aastal avatakse viis hoovi, mille valikul arvestatakse eelkõige muinsuskaitseameti hinnangut iga hoovi kohta.', 'Esimesel aastal avatakse viis hoovi, mille valikul arvestatakse eelkõige muinsuskaitseameti hinnanguga iga hoovi kohta.'], ['Elanikud on aastaid kannatanud öise lärmiga, mistõttu nad kardavad hoovi avamist.', 'Elanikud on aastaid kannatanud öise lärmi all, mistõttu nad kardavad hoovi avamist.']]),
      B.planning('c1_020_t_prep', 'Plaan.', 'Kirjuta märksõnad: arvamusloo jaoks 5 minutit, kõne jaoks 3 minutit.', ['Arvamuslugu: seisukoht ja pealkiri.', 'Punkt 1: avalik huvi ja elanike privaatsus – kumb kaalub üles? Näide.', 'Punkt 2: kes peaks kandma kulud ja vastutuse? Näide.', 'Kõne: valitud teema, kolm märksõna ja kokkuvõtte lause.']),
      B.letter('c1_020_t_w2', 'Kirjutamine 2: arvamuslugu (220–260 sõna).', 'Kirjuta ajalehele arvamuslugu „Kas vanalinna hoovid tuleks avada kõigile?”. Arenda mõlemat punkti, too näiteid ja tee järeldus. Pöördu avalikkuse poole, ära mine isiklikuks.', 'Pealkiri:', 'Autor:', [220, 260]),
      B.speaking('c1_020_t_say', 'Rääkimine 1: kõne (2 minutit).', 'Vali kaardilt üks teema. Valmistu 3 minutit ja räägi 2 minutit: pöördumine, arendus, lühike kokkuvõte. Partner esitab seejärel 1–2 küsimust.', ['Teema A: Kuidas kaasata linnaosa elanikke otsuste tegemisse?', 'Teema B: Milline kohalik teenus vajab kõige rohkem parandamist ja kuidas seda mõõta?', 'Partneri küsimus: Kes peaks selle eest maksma?', 'Partneri küsimus: Kuidas tead aasta pärast, et muutus õnnestus?'], [100, 140], ['Lubage mul alustada…', '… hinnangul', 'Kokkuvõtteks…']),
      B.rolecards('c1_020_t_disc', 'Rääkimine 2: arutelu (umbes 7 minutit).', 'Arutlege teemakaardi põhjal. Võtke ja andke sõna, põhjendage näidetega. Ärge pidage monoloogi.',
        'Teemakaart: „Kaasav eelarve: päris otsustusõigus või sümboolne žest?” Mõtted: väike summa; madal osalus; usaldus ametnike vastu; noorte kaasamine. Alusta oma seisukohaga ja küsi partneri arvamust.', 'Sama teemakaart. Ole osaliselt eri meelt, too näide oma kodukohast, võta viisakalt sõna ja anna see tagasi. Lõpus võtke koos kokku, milles olete ühel meelel.',
        ['Minu meelest…, aga mida sina arvad?', 'Kui tohin vahele öelda…', 'Tulles tagasi sinu näite juurde…'], ['Ma näen seda veidi teisiti…', 'Lubage mul mõte lõpetada…', 'Kas oleme siis ühel meelel, et…?']),
      B.rubric('c1_020_t_score', 'Hindamine (Harno C1).', 'Õpetaja või paariline märgib punktid.', ['Kirjutamine 1 (Avasta leht): üldistus, võrdlus, 2–3 arvu, neutraalne toon, umbes 180 sõna … / 12', 'Kirjutamine 2: mõlemad punktid arendatud, näited, sissejuhatus ja järeldus, 220–260 sõna … / 12', 'Rääkimine 1: ülesehitus, register, vastused küsimustele … / 10', 'Rääkimine 2: sõna võtmine ja andmine, põhjendused ja näited … / 10', 'Kokku: kirjutamine … / 24, rääkimine … / 20; lävend 60% kummaski osas.']),
      B.selfcheck('c1_020_t_self', ['Kirjutamine: sain vähemalt 15 punkti 24-st (60%).', 'Rääkimine: sain vähemalt 12 punkti 20-st (60%).', 'Ma eristasin oma seisukohta teiste omast.', 'Arutelus võtsin ja andsin sõna ega pidanud monoloogi.'], 'Moodul 2 läbitud'),
    ],
